}

function updateRateMetrics(now) {
  const elapsed = now - rateWindowStartedAt;
  if (elapsed < 1000) return;
  const scale = 1000 / elapsed;
  document.querySelector("#camera-fps").textContent = (cameraFrames * scale).toFixed(1) + " FPS";
  document.querySelector("#render-fps").textContent = (renderFrames * scale).toFixed(1) + " FPS";
  document.querySelector("#fps").textContent = (aiResponses * scale).toFixed(1) + " FPS";
  document.querySelector("#skipped-frames").textContent = String(skippedFrames);
  cameraFrames = 0;
  renderFrames = 0;
  aiResponses = 0;
  rateWindowStartedAt = now;
}

function observeVideoFrames() {
  if (!media || !video.requestVideoFrameCallback) return;
  videoFrameHandle = video.requestVideoFrameCallback(() => {
    cameraFrames += 1;
    observeVideoFrames();
  });
}

function canvasPoint(event) {
  const rect = canvas.getBoundingClientRect();
  return [
    (event.clientX - rect.left) * canvas.width / rect.width,
    (event.clientY - rect.top) * canvas.height / rect.height,
  ];
}

canvas.addEventListener("pointerdown", (event) => {
  if (!frozen || !manualEnabled) return;
  canvas.setPointerCapture(event.pointerId);
  dragStart = canvasPoint(event);
  draftBox = [dragStart[0], dragStart[1], dragStart[0], dragStart[1]];
});
canvas.addEventListener("pointermove", (event) => {
  if (!dragStart || !frozen) return;
  const point = canvasPoint(event);
  draftBox = [
    Math.min(dragStart[0], point[0]), Math.min(dragStart[1], point[1]),
    Math.max(dragStart[0], point[0]), Math.max(dragStart[1], point[1]),
  ];
  confirmBtn.disabled = draftBox[2] - draftBox[0] < 8 || draftBox[3] - draftBox[1] < 8;
});
canvas.addEventListener("pointerup", (event) => {
  if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
  dragStart = null;
});
canvas.addEventListener("pointercancel", (event) => {
  if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
  dragStart = null;
});

function toBlob(target, quality = JPEG_QUALITY) {
  return new Promise((resolve, reject) => {
    target.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("摄像头帧编码失败"));
    }, "image/jpeg", quality);
  });
}

function liveStatus() {
  if (latest?.state === "TRACKING") return "设备跟踪中：原画连续显示，AI 结果正在安全平滑。";
  if (latest?.state === "UNCERTAIN") return "当前跟踪不确定，接触点已暂停；完全丢失后请重新框选。";
  if (latest?.state === "CANDIDATE") return "正在确认自动候选；也可以直接冻结画面并手动画框。";
  return manualEnabled ? "请冻结当前画面并手动画框，或等待自动搜索结果。" : "系统正在自动搜索设备。";
}

async function sendFrame() {
  if (!media || frozen || !video.videoWidth) return;
  if (inFlight) {
    skippedFrames += 1;
    return;
  }
  inFlight = true;
  captureCtx.drawImage(video, 0, 0, capture.width, capture.height);
  const id = frameId++;
  const sentAt = performance.now();
  try {
    const body = await toBlob(capture, JPEG_QUALITY);
    const response = await fetch("/v1/stream/frame", {
      method: "POST",
      headers: {
        "Content-Type": "image/jpeg",
        "x-frame-id": String(id),
        "x-capture-timestamp-ms": String(Date.now()),
      },
      body,
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    const receivedAt = performance.now();
    rememberResult(data.result, receivedAt);
    aiResponses += 1;
    updateResultMetrics(sentAt, receivedAt);
    status(liveStatus(), latest.needs_review && latest.state !== "SEARCHING");
  } catch (error) {
    status("推理请求失败：" + error.message, true);
  } finally {
    inFlight = false;
  }
}

async function runAiLoop() {
  if (!media) return;
  const cycleStartedAt = performance.now();
  if (frozen) {
    requestTimer = setTimeout(runAiLoop, 40);
    return;
  }
  await sendFrame();
  const cycleMs = performance.now() - cycleStartedAt;
  if (cycleMs > AI_INTERVAL_MS) {
    skippedFrames += Math.max(1, Math.floor(cycleMs / AI_INTERVAL_MS) - 1);
  }
  if (media) {
    requestTimer = setTimeout(runAiLoop, Math.max(0, AI_INTERVAL_MS - cycleMs));
}
}

function updateResultMetrics(sentAt, receivedAt) {
  document.querySelector("#state").textContent = latest.state || latest.track_state;
  document.querySelector("#source").textContent = latest.assist_source || "-";
  document.querySelector("#marker-ids").textContent = (latest.visible_marker_ids || []).join(", ") || "无";
  document.querySelector("#marker-source").textContent = latest.marker_source || "none";
  document.querySelector("#marker-score").textContent = Number(latest.marker_confidence || 0).toFixed(3);
  document.querySelector("#device-score").textContent =
    Number(latest.device_score || latest.detector_score || 0).toFixed(3);
  document.querySelector("#contact-state").textContent =
    latest.contact_visibility || "not_annotatable";
  document.querySelector("#latency").textContent =
    Number(latest.timings_ms?.total || 0).toFixed(1) + " / " +
    (receivedAt - sentAt).toFixed(1) + " ms";
}

async function start() {
  try {
    media = await navigator.mediaDevices.getUserMedia({
      video: {width: {ideal: 960}, height: {ideal: 540}, frameRate: {ideal: 30, max: 30}},
      audio: false,
    });
    video.srcObject = media;
    await video.play();
    fit();
    startBtn.disabled = true;
    freezeBtn.disabled = !manualEnabled;
    resetBtn.disabled = false;
    stopBtn.disabled = false;
    frameId = 0;
    skippedFrames = 0;
    boxSamples = [];
    pointSamples = [];
    observeVideoFrames();
    if (!renderHandle) renderHandle = requestAnimationFrame(paint);
    requestTimer = setTimeout(runAiLoop, 0);
    status("摄像头已启动。请冻结画面并框选设备；原画约 30 FPS，AI 目标 8–12 FPS。");
  } catch (error) {
    status("无法打开摄像头：" + error.message, true);
  }
}

function freezeFrame() {
  if (!media || !manualEnabled) return;
  fit();
  seedCtx.drawImage(video, 0, 0, seed.width, seed.height);
  frozen = true;
  draftBox = null;
  dragStart = null;
  latest = null;
  boxSamples = [];
  pointSamples = [];
  stage.classList.add("selecting");
  freezeBtn.disabled = true;
  confirmBtn.disabled = true;
  cancelBtn.disabled = false;
  status("画面已冻结，请拖动框选设备。");
}

function cancelSelection() {
  frozen = false;
  draftBox = null;
  dragStart = null;
  stage.classList.remove("selecting");
  freezeBtn.disabled = !media || !manualEnabled;
  confirmBtn.disabled = true;
  cancelBtn.disabled = true;
  status("已取消框选，摄像头继续运行。");
}

async function confirmSelection() {
  if (!draftBox || inFlight) return;
  inFlight = true;
  confirmBtn.disabled = true;
  try {
    const body = await toBlob(seed, 0.85);
    const id = frameId++;
    const response = await fetch("/v1/assist/manual/init", {
      method: "POST",
      headers: {
        "Content-Type": "image/jpeg",
        "x-frame-id": String(id),
        "x-capture-timestamp-ms": String(Date.now()),
        "x-bbox-x1": String(draftBox[0]),
        "x-bbox-y1": String(draftBox[1]),
        "x-bbox-x2": String(draftBox[2]),
        "x-bbox-y2": String(draftBox[3]),
      },
      body,
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    rememberResult(data.result, performance.now());
    frozen = false;
    draftBox = null;
    stage.classList.remove("selecting");
    freezeBtn.disabled = false;
    cancelBtn.disabled = true;
    status("设备框初始化成功，正在进行流畅跟踪。");
  } catch (error) {
    status("手动画框初始化失败：" + error.message, true);
    confirmBtn.disabled = false;
  } finally {
    inFlight = false;
  }
}

async function reset() {
  if (inFlight) return;
  await fetch("/v1/stream/reset", {method: "POST"});
  latest = null;
  latestReceivedAt = 0;
  boxSamples = [];
  pointSamples = [];
  frameId = 0;
  frozen = false;
  draftBox = null;
  stage.classList.remove("selecting");
  freezeBtn.disabled = !media || !manualEnabled;
  confirmBtn.disabled = true;
  cancelBtn.disabled = true;
  status("状态已清除，请重新冻结画面并框选设备。");
}

async function stop() {
  if (requestTimer) clearTimeout(requestTimer);
  requestTimer = null;
  if (renderHandle) cancelAnimationFrame(renderHandle);
  renderHandle = null;
  if (videoFrameHandle !== null && video.cancelVideoFrameCallback) {
    video.cancelVideoFrameCallback(videoFrameHandle);
  }
  videoFrameHandle = null;
  if (media) media.getTracks().forEach((track) => track.stop());
  media = null;
  await reset();
  startBtn.disabled = false;
  freezeBtn.disabled = true;
  resetBtn.disabled = true;
  stopBtn.disabled = true;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  status("摄像头已停止。");
}

manualModeBtn.addEventListener("click", () => updateModes(!manualEnabled, markerEnabled));
markerModeBtn.addEventListener("click", () => updateModes(manualEnabled, !markerEnabled));
backgroundBtn.addEventListener("click", () => {
  whitenBackground = !whitenBackground;
  backgroundBtn.textContent = "背景漂白：" + (whitenBackground ? "开" : "关");
});
startBtn.addEventListener("click", start);
freezeBtn.addEventListener("click", freezeFrame);
confirmBtn.addEventListener("click", confirmSelection);
cancelBtn.addEventListener("click", cancelSelection);
resetBtn.addEventListener("click", reset);
stopBtn.addEventListener("click", stop);

configurePageCopy();
fetch("/health")
  .then((response) => response.json())
  .then((data) => {
    if (!data.ok) throw new Error("服务未就绪");
    applyModes(data.assist_modes || {});
    status("服务已就绪。默认使用手动画框辅助；AprilTag 已关闭。");
  })
  .catch((error) => status("服务未启动：" + error.message, true));

