async function saveInferenceSettings() {
  applyInferenceBtn.disabled = true;
  try {
    const response = await fetch("/v1/debug/inference-settings", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify(readInferenceSettings()),
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    applyInferenceSettings(data.settings);
    if (data.tracker_reset) {
      latest = null;
      latestReceivedAt = 0;
      boxSamples = [];
      pointSamples = [];
      status("模型输入配置已生效，旧跟踪状态已安全清空，请重新框选或等待搜索。");
    } else {
      status("页面显示配置已生效，当前跟踪未中断。");
    }
  } catch (error) {
    status("模型输入配置保存失败：" + error.message, true);
  } finally {
    applyInferenceBtn.disabled = false;
  }
}

function applyPreset(name) {
  const presets = {
    recommended: {
      view_mode: "debug",
      display_background: "raw",
      processed_background: "white",
      foreground_scope: "person",
      detector_input: "processed",
      sam2_input: "raw",
      contact_input: "raw",
