      view_mode: "debug",
      display_background: "raw",
      processed_background: "white",
      foreground_scope: "person",
      detector_input: "raw",
      sam2_input: "raw",
      contact_input: "raw",
    },
    processed: {
      view_mode: "debug",
      display_background: "white",
      processed_background: "white",
      foreground_scope: "person",
      detector_input: "processed",
      sam2_input: "processed",
      contact_input: "processed",
    },
    face: {
      view_mode: "debug",
      display_background: "white",
      processed_background: "white",
      foreground_scope: "face_near",
      detector_input: "processed",
      sam2_input: "raw",
      contact_input: "raw",
    },
  };
  const preset = presets[name];
  if (!preset) return;
  applyInferenceSettings({...readInferenceSettings(), ...preset});
  saveInferenceSettings();
}

