  const duration = Math.max(current.time - previous.time, 1);
  if (targetTime <= current.time) {
    const alpha = Math.max(0, Math.min(1, (targetTime - previous.time) / duration));
    return current.value.map((value, index) =>
      previous.value[index] + (value - previous.value[index]) * alpha);
  }

