from __future__ import annotations

import asyncio
import os
import time
from contextlib import asynccontextmanager
from io import BytesIO
from pathlib import Path

from fastapi import FastAPI, Request
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from PIL import Image

from scripts.generate_marker_print_assets import generate as generate_marker_print_assets
from src.assist_modes import AssistModeConfig
from src.zero_touch_tracker import ZeroTouchLiveTracker

PROJECT_ROOT = Path(__file__).resolve().parent
SOURCE_ROOT = Path(os.environ.get("MEDVISION_PROJECT_ROOT", str(PROJECT_ROOT))).resolve()
WEB_ROOT = PROJECT_ROOT / "web" / "assist_stream"
MARKER_PRINT_ROOT = PROJECT_ROOT / "artifacts" / "marker_vstream_30mm"
MARKER_PRINT_SHEET = (
    MARKER_PRINT_ROOT / "print_sheet_a4_30mm.pdf"
)


def decode_image(payload: bytes) -> Image.Image:
    if not payload:
        raise ValueError("å›¾åƒå†…å®¹ä¸ºç©º")
    with Image.open(BytesIO(payload)) as source:
        return source.copy()


def header_int(request: Request, name: str) -> int:
    value = request.headers.get(name)
    if value is None:
        raise ValueError(f"ç¼ºå°‘è¯·æ±‚å¤´ {name}")
    return int(value)


def header_float(request: Request, name: str) -> float:
    value = request.headers.get(name)
    if value is None:
        raise ValueError(f"missing request header {name}")
    return float(value)


@asynccontextmanager
async def lifespan(app: FastAPI):
    if not MARKER_PRINT_SHEET.is_file():
        await asyncio.to_thread(generate_marker_print_assets, MARKER_PRINT_ROOT)
    assist_config = AssistModeConfig.load(SOURCE_ROOT)
    tracker = await asyncio.to_thread(ZeroTouchLiveTracker, SOURCE_ROOT, assist_config)
    app.state.tracker = tracker
    app.state.assist_config = assist_config
    try:
        yield
    finally:
        await asyncio.to_thread(tracker.close)


app = FastAPI(title="åŒ»ç¾Žè®¾å¤‡é›¶æŽ¥è§¦è‡ªåŠ¨è·Ÿè¸ªæ¼”ç¤º", lifespan=lifespan)
app.mount("/assets", StaticFiles(directory=WEB_ROOT), name="assets")


@app.get("/")
async def index() -> FileResponse:
    return FileResponse(WEB_ROOT / "index.html")


@app.get("/marker-print-sheet")
async def marker_print_sheet():
    if not MARKER_PRINT_SHEET.is_file():
        return JSONResponse(
            {"ok": False, "error": "30 mm marker print sheet has not been generated"},
            status_code=404,
        )
    return FileResponse(
        MARKER_PRINT_SHEET,
        media_type="application/pdf",
        filename="medical_device_apriltag_30mm_a4.pdf",
    )


@app.get("/health")
async def health() -> JSONResponse:
    tracker: ZeroTouchLiveTracker = app.state.tracker
    return JSONResponse({
        "ok": True,
        "service": "zero-touch-auto-reacquire-v1",
        "backend": "python-cuda-demo",
        "tracker": tracker.status(),
        "assist_modes": tracker.assist_config.as_dict(),
        "inference_settings": tracker.inference_settings.as_dict(),
        "product_scope": "single_subject_demo_cross_subject_not_validated",
        "production_ready": False,
    })


@app.get("/v1/debug/inference-settings")
async def get_inference_settings() -> JSONResponse:
    return JSONResponse(
        {
            "ok": True,
            "settings": app.state.tracker.inference_settings.as_dict(),
        }
    )


@app.post("/v1/debug/inference-settings")
async def configure_inference_settings(request: Request) -> JSONResponse:
    try:
        payload = await request.json()
        if not isinstance(payload, dict):
            raise ValueError("settings payload must be a JSON object")
        payload.pop("configuration_hash", None)
        result = await asyncio.to_thread(
            app.state.tracker.configure_inference_settings,
            payload,
        )
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse({"ok": True, **result})


@app.post("/v1/stream/frame")
async def process_frame(request: Request) -> JSONResponse:
    try:
        image = decode_image(await request.body())
        frame_id = header_int(request, "x-frame-id")
        timestamp_ms = header_int(request, "x-capture-timestamp-ms")
        result = await asyncio.to_thread(
            app.state.tracker.process,
            image,
            frame_id=frame_id,
            timestamp_ms=timestamp_ms,
        )
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse({"ok": True, "result": result})


@app.post("/v1/assist/modes")
async def configure_assist_modes(request: Request) -> JSONResponse:
    try:
        payload = await request.json()
        manual = payload.get("enable_manual_bbox_assist")
        marker = payload.get("enable_marker_assist")
        if not isinstance(manual, bool) or not isinstance(marker, bool):
            raise ValueError("both assist mode values must be boolean")
        result = await asyncio.to_thread(
            app.state.tracker.configure_assist_modes,
            enable_manual_bbox_assist=manual,
            enable_marker_assist=marker,
        )
        app.state.assist_config = app.state.tracker.assist_config
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse(
        {"ok": True, "assist_modes": app.state.tracker.assist_config.as_dict(), "tracker": result}
    )


@app.post("/v1/assist/manual/init")
@app.post("/v1/track/init")
async def initialize_manual_assist(request: Request) -> JSONResponse:
    if not app.state.tracker.assist_config.enable_manual_bbox_assist:
        return JSONResponse(
            {"ok": False, "error": "manual bbox assist is disabled"}, status_code=403
        )
    try:
        image = decode_image(await request.body())
        box = (
            header_float(request, "x-bbox-x1"),
            header_float(request, "x-bbox-y1"),
            header_float(request, "x-bbox-x2"),
            header_float(request, "x-bbox-y2"),
        )
        frame_id = header_int(request, "x-frame-id")
        timestamp_ms = header_int(request, "x-capture-timestamp-ms")
        result = await asyncio.to_thread(
            app.state.tracker.initialize_manual,
            image,
            box,
            frame_id=frame_id,
            timestamp_ms=timestamp_ms,
        )
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse({"ok": True, "result": result})


@app.post("/v1/stream/reset")
async def reset_stream() -> JSONResponse:
    result = await asyncio.to_thread(app.state.tracker.reset)
    return JSONResponse({"ok": True, "result": result})


