from typing import Any
from uuid import uuid4

import numpy as np
from PIL import Image, ImageOps

ALLOWED_SPLITS = {"train", "val", "test", "cross_subject_test"}
ALLOWED_KINDS = {
    "correct_as_is", "bbox_corrected", "contact_corrected",
    "false_positive_no_device", "missed_device_manual",
