    "sharpness_score", "inference_configuration_hash", "annotation_state",
)


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _atomic(path: Path, payload: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid4().hex}.tmp")
    temporary.write_bytes(payload)
    temporary.replace(path)


def _append(path: Path, fields: tuple[str, ...], row: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    new = not path.exists()
    with path.open("a", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields)
        if new:
            writer.writeheader()
        writer.writerow({field: row.get(field, "") for field in fields})


def _jpeg(value: str) -> bytes:
    if not isinstance(value, str) or "," not in value:
        raise ValueError("raw_image must be a JPEG data URL")
    header, encoded = value.split(",", 1)
    if header.lower() not in {"data:image/jpeg;base64", "data:image/jpg;base64"}:
        raise ValueError("raw_image must use image/jpeg base64 encoding")
    try:
        return base64.b64decode(encoded, validate=True)
    except Exception as exc:
        raise ValueError("raw_image contains invalid base64 data") from exc


def _phash(image: Image.Image) -> str:
    pixels = np.asarray(
        image.convert("L").resize((32, 32), Image.Resampling.LANCZOS), dtype=np.float64
    )
    n = 32
    x = np.arange(n)
    basis = np.cos((2 * x[:, None] + 1) * x[None, :] * np.pi / (2 * n))
    basis[:, 0] /= np.sqrt(2)
    dct = (2 / n) * basis.T @ pixels @ basis
    low = dct[:8, :8].reshape(-1)
    bits = low > float(np.median(low[1:]))
    return f"{int(''.join('1' if bit else '0' for bit in bits), 2):016x}"


def _hamming(left: str, right: str) -> int:
    return (int(left, 16) ^ int(right, 16)).bit_count()


def _sharpness(image: Image.Image) -> float:
    gray = np.asarray(image.convert("L").resize((320, 180)), dtype=np.float32)
    lap = (
        -4 * gray[1:-1, 1:-1] + gray[:-2, 1:-1] + gray[2:, 1:-1]
        + gray[1:-1, :-2] + gray[1:-1, 2:]
    )
    return float(np.var(lap))


def _bbox(value: Any, width: int, height: int) -> list[float] | None:
    if value is None:
        return None
    if not isinstance(value, list) or len(value) != 4:
        raise ValueError("bbox must be [x1,y1,x2,y2] or null")
    x1, y1, x2, y2 = map(float, value)
    if not (0 <= x1 < x2 <= width and 0 <= y1 < y2 <= height):
        raise ValueError("bbox is invalid or outside the image")
    if x2 - x1 < 4 or y2 - y1 < 4:
        raise ValueError("bbox is too small")
    return [x1, y1, x2, y2]


