    <div id="al-counts" class="active-counts">正在读取采集进度...</div>
    <div id="active-editor-wrap">
      <div class="active-fields">
        <label>困难样本类型<select id="al-kind"><option value="correct_as_is">预测正确，直接确认</option><option value="bbox_corrected">设备框已校正</option><option value="contact_corrected">接触点已校正</option><option value="false_positive_no_device">误报：实际无设备</option><option value="missed_device_manual">漏检：人工补框</option></select></label>
        <label>编辑工具<select id="al-tool"><option value="adjust">拖动框/角点调整</option><option value="draw">重新画设备框</option><option value="contact">点击接触点</option></select></label>
        <label>接触可见性<select id="al-visibility"><option value="visible">visible</option><option value="occluded_inferable">occluded_inferable</option><option value="not_annotatable">not_annotatable</option></select></label>
      </div>
      <canvas id="active-editor"></canvas>
      <div class="active-actions">
        <button id="al-use-prediction" class="secondary">恢复当前模型草稿</button>
        <button id="al-clear-contact" class="secondary">清空接触点</button>
        <button id="al-save-device" class="positive">确认保存 device</button>
        <button id="al-save-negative" class="negative">确认保存 no_device</button>
        <button id="al-cancel" class="secondary">放弃本张</button>
      </div>
      <div id="al-editor-state" class="active-dirty">当前草稿尚未保存。</div>
    </div>
  \`;
  const insertion = document.querySelector(".steps") || document.querySelector("main").lastElementChild;
  insertion.before(panel);

  const $ = selector => panel.querySelector(selector);
  const canvas = $("#active-editor");
  const context = canvas.getContext("2d");
  const wrap = $("#active-editor-wrap");
  let session = null;
  let rawDataUrl = null;
  let frozenImage = null;
  let prediction = {};
  let draftBox = null;
  let draftPoint = null;
  let captureTimestamp = 0;
  let pointer = null;

  function streamState() {
    return window.medvisionStreamState || null;
  }

  function message(text, error = false) {
    const element = $("#al-editor-state");
    element.textContent = text;
    element.className = error ? "active-dirty" : "active-saved";
  }

  function validBox(box) {
    return Array.isArray(box) && box.length === 4 && box[2] - box[0] >= 4 && box[3] - box[1] >= 4;
  }

  function validPoint(point) {
    return Array.isArray(point) && point.length === 2;
  }

  function draw() {
    if (!frozenImage) return;
    context.drawImage(frozenImage, 0, 0, canvas.width, canvas.height);
    if (validBox(draftBox)) {
      const [x1,y1,x2,y2] = draftBox;
      context.save();
      context.strokeStyle = "#ffd64a";
      context.lineWidth = 4;
      context.setLineDash([12,7]);
      context.strokeRect(x1,y1,x2-x1,y2-y1);
      context.setLineDash([]);
      context.fillStyle = "#ffd64a";
      for (const [x,y] of [[x1,y1],[x2,y1],[x1,y2],[x2,y2]]) context.fillRect(x-6,y-6,12,12);
      context.font = "bold 18px sans-serif";
      context.fillText("人工草稿 DEVICE", x1+7, Math.max(22,y1+22));
      context.restore();
    }
    if (validPoint(draftPoint)) {
      const [x,y] = draftPoint;
      context.save();
      context.strokeStyle = "#b23cff";
      context.fillStyle = "#b23cff";
      context.lineWidth = 5;
      context.beginPath(); context.arc(x,y,10,0,Math.PI*2); context.stroke();
      context.beginPath(); context.moveTo(x-18,y); context.lineTo(x+18,y); context.moveTo(x,y-18); context.lineTo(x,y+18); context.stroke();
      context.font = "bold 18px sans-serif"; context.fillText("接触点草稿",x+14,y-14);
      context.restore();
    }
  }

  function pointOf(event) {
    const rect = canvas.getBoundingClientRect();
    return [(event.clientX-rect.left)*canvas.width/rect.width,(event.clientY-rect.top)*canvas.height/rect.height];
  }

  function hit(point) {
    if (!validBox(draftBox)) return {kind:"draw"};
    const [x,y] = point, [x1,y1,x2,y2] = draftBox, radius = Math.max(12,canvas.width*0.012);
    const corners = [[x1,y1,0],[x2,y1,1],[x1,y2,2],[x2,y2,3]];
    for (const [cx,cy,index] of corners) if (Math.hypot(x-cx,y-cy)<=radius) return {kind:"corner",index};
    if (x>=x1 && x<=x2 && y>=y1 && y<=y2) return {kind:"move"};
    return {kind:"draw"};
  }

  canvas.addEventListener("pointerdown", event => {
    if (!frozenImage) return;
    const point = pointOf(event), tool = $("#al-tool").value;
    canvas.setPointerCapture(event.pointerId);
    if (tool === "contact") {
      draftPoint = point;
      $("#al-visibility").value = "visible";
      $("#al-kind").value = "contact_corrected";
      message("接触点草稿已修改，尚未保存。", true);
      draw();
      return;
    }
    pointer = {start:point, original:draftBox ? [...draftBox] : null, action:tool==="draw"?{kind:"draw"}:hit(point)};
    if (pointer.action.kind === "draw") draftBox = [point[0],point[1],point[0],point[1]];
  });

  canvas.addEventListener("pointermove", event => {
    if (!pointer) return;
    const [x,y] = pointOf(event), [sx,sy] = pointer.start;
    if (pointer.action.kind === "draw") draftBox=[Math.min(sx,x),Math.min(sy,y),Math.max(sx,x),Math.max(sy,y)];
    else if (pointer.action.kind === "move") {
      const [x1,y1,x2,y2]=pointer.original, dx=x-sx,dy=y-sy,w=x2-x1,h=y2-y1;
      const nx=Math.max(0,Math.min(canvas.width-w,x1+dx)),ny=Math.max(0,Math.min(canvas.height-h,y1+dy));
      draftBox=[nx,ny,nx+w,ny+h];
    } else if (pointer.action.kind === "corner") {
      const box=[...pointer.original], i=pointer.action.index;
      if(i===0){box[0]=x;box[1]=y} if(i===1){box[2]=x;box[1]=y}
      if(i===2){box[0]=x;box[3]=y} if(i===3){box[2]=x;box[3]=y}
      draftBox=[Math.min(box[0],box[2]),Math.min(box[1],box[3]),Math.max(box[0],box[2]),Math.max(box[1],box[3])];
    }
    $("#al-kind").value = prediction.device_bbox ? "bbox_corrected" : "missed_device_manual";
    message("设备框草稿已修改，尚未保存。", true);
    draw();
  });

  function release(event) {
    if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
    pointer = null;
  }
  canvas.addEventListener("pointerup", release);
  canvas.addEventListener("pointercancel", release);

  function loadPrediction() {
    draftBox = validBox(prediction.device_bbox) ? prediction.device_bbox.map(Number) :
      (validBox(prediction.diagnostic_bbox) ? prediction.diagnostic_bbox.map(Number) : null);
    draftPoint = validPoint(prediction.contact_point) ? prediction.contact_point.map(Number) : null;
    $("#al-visibility").value = prediction.contact_visibility || (draftPoint ? "visible" : "not_annotatable");
    $("#al-kind").value = draftBox ? "correct_as_is" : "missed_device_manual";
    draw();
    message("已加载当前模型草稿，请人工确认后保存。", true);
  }

  async function freezeSample() {
    const state = streamState();
    const video = state?.video();
    if (!session || !video || !video.videoWidth) {
      message("请先启动采集 session 和摄像头。", true); return;
    }
    const source = document.createElement("canvas");
    source.width=video.videoWidth; source.height=video.videoHeight;
    source.getContext("2d").drawImage(video,0,0,source.width,source.height);
    rawDataUrl=source.toDataURL("image/jpeg",0.90);
    captureTimestamp=Date.now();
    prediction=JSON.parse(JSON.stringify(state.latest() || {}));
    frozenImage=new Image();
    await new Promise((resolve,reject)=>{frozenImage.onload=resolve;frozenImage.onerror=reject;frozenImage.src=rawDataUrl});
    canvas.width=source.width;canvas.height=source.height;
    wrap.classList.add("open");
    loadPrediction();
  }

  async function save(status) {
    if (!rawDataUrl || !session) return;
    const visibility = status==="no_device" ? "not_annotatable" : $("#al-visibility").value;
    const payload = {
      annotation_state:"confirmed", raw_image:rawDataUrl, capture_timestamp_ms:captureTimestamp,
      status, sample_kind:status==="no_device" ? "false_positive_no_device" : $("#al-kind").value,
      bbox:status==="device" ? draftBox : null,
      contact_point:status==="device" && visibility!=="not_annotatable" ? draftPoint : null,
      contact_visibility:visibility, prediction_snapshot:prediction,
      inference_settings:streamState()?.settings() || {},
    };
    try {
      const response=await fetch("/v1/active-learning/sample",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});
      const data=await response.json();
      if(!data.ok) throw new Error(data.error);
      message("已确认保存："+data.sample.sample_id);
      rawDataUrl=frozenImage=null;draftBox=draftPoint=null;wrap.classList.remove("open");
      renderStatus(data.status);
    } catch(error) { message("保存失败："+error.message,true); }
  }

  function renderStatus(data) {
    session=data.active_session || null;
    $("#al-session-state").textContent=session ? \`采集中：\${session.session_id} / \${session.split}\` : "尚未开始采集 session。";
    $("#al-session-state").className=session?"active-saved":"active-dirty";
    $("#al-start").disabled=Boolean(session);$("#al-stop").disabled=!session;
    $("#al-freeze").disabled=!session;
    const c=data.counts||{},r=data.remaining||{};
    $("#al-counts").textContent =
      \`train: \${c.train?.device||0} 正 / \${c.train?.no_device||0} 负，剩余 \${r.train?.device||0} 正 / \${r.train?.no_device||0} 负\\n\`+
      \`val: \${c.val?.device||0} 正 / \${c.val?.no_device||0} 负，剩余 \${r.val?.device||0} 正 / \${r.val?.no_device||0} 负\\n\`+
      \`test: \${c.test?.device||0} 正 / \${c.test?.no_device||0} 负，剩余 \${r.test?.device||0} 正 / \${r.test?.no_device||0} 负\\n\`+
      \`训练门禁：\${data.training_ready?"已达到":"未达到，不会启动训练"}\`;
  }

  $("#al-start").addEventListener("click",async()=>{
    try{
      const payload={anonymous_subject_id:$("#al-subject").value,split:$("#al-split").value,background_id:$("#al-background").value,glasses:$("#al-glasses").value,lighting:$("#al-lighting").value};
      const response=await fetch("/v1/active-learning/session/start",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});
      const data=await response.json();if(!data.ok)throw new Error(data.error);renderStatus(data);
    }catch(error){message("Session 启动失败："+error.message,true)}
  });
  $("#al-stop").addEventListener("click",async()=>{const response=await fetch("/v1/active-learning/session/stop",{method:"POST"});renderStatus(await response.json())});
  $("#al-freeze").addEventListener("click",freezeSample);
  $("#al-use-prediction").addEventListener("click",loadPrediction);
  $("#al-clear-contact").addEventListener("click",()=>{draftPoint=null;$("#al-visibility").value="not_annotatable";draw();message("接触点已清空，尚未保存。",true)});
  $("#al-save-device").addEventListener("click",()=>save("device"));
  $("#al-save-negative").addEventListener("click",()=>save("no_device"));
  $("#al-cancel").addEventListener("click",()=>{rawDataUrl=frozenImage=null;draftBox=draftPoint=null;wrap.classList.remove("open")});
  fetch("/v1/active-learning/status").then(response=>response.json()).then(renderStatus).catch(error=>message("读取采集状态失败："+error.message,true));
})();
`;
