                glasses=str(metadata.get("glasses", "unknown")).strip() or "unknown",
                lighting=str(metadata.get("lighting", "unknown")).strip() or "unknown",
                started_at=_now(),
            )
            self._last_timestamp_ms = None
            _append_session(self.manifest_root / "sessions.csv", asdict(self._active))
            return self.status()

    def stop_session(self) -> dict[str, Any]:
        with self._lock:
            if self._active:
                self._active.stopped_at = _now()
                session_root = self.data_root / self._active.split / self._active.session_id
                _atomic(
                    session_root / "session_closed.json",
                    json.dumps(asdict(self._active), ensure_ascii=False, indent=2).encode("utf-8"),
                )
            self._active = None
            self._last_timestamp_ms = None
            return self.status()

    def _validate_label(
        self,
        payload: dict[str, Any],
        width: int,
        height: int,
    ) -> tuple[str, str, list[float] | None, list[float] | None, str]:
        status = str(payload.get("status", ""))
        kind = str(payload.get("sample_kind", "correct_as_is"))
        visibility = str(payload.get("contact_visibility", "not_annotatable"))
        if status not in {"device", "no_device"}:
            raise ValueError("样本状态必须是 device 或 no_device")
        if kind not in KINDS:
            raise ValueError("困难样本类型不合法")
        if visibility not in VISIBILITY:
            raise ValueError("接触可见性不合法")
        bbox = _bbox(payload.get("bbox"), width, height)
        point = _point(payload.get("contact_point"), width, height)
        if status == "no_device":
            if bbox is not None or point is not None:
                raise ValueError("无设备样本不能包含设备框或接触点")
            visibility = "not_annotatable"
        elif bbox is None:
            raise ValueError("设备样本缺少设备框，当前帧不能快速保存")
        elif visibility == "not_annotatable":
            point = None
        elif point is None:
            visibility = "not_annotatable"
        return status, kind, bbox, point, visibility

    def _nearest(self, phash: str, session_id: str) -> tuple[dict[str, str] | None, int]:
        candidates = [
            row for row in self._rows()
            if row.get("session_id") == session_id
            and row.get("review_state") != "deleted"
            and row.get("perceptual_hash")
        ]
        if not candidates:
            return None, 64
        nearest = min(candidates, key=lambda row: _hamming(phash, row["perceptual_hash"]))
        return nearest, _hamming(phash, nearest["perceptual_hash"])

    def _save(self, payload: dict[str, Any], review_state: str) -> dict[str, Any]:
        session = self._active
        if not session:
            raise RuntimeError("请先创建采集 Session")
        timestamp = int(payload.get("capture_timestamp_ms", 0))
        if timestamp <= 0:
            raise ValueError("采集时间戳无效，请重新保存")
        if (
            self._last_timestamp_ms is not None
            and timestamp - self._last_timestamp_ms < self.min_interval_ms
        ):
            raise ValueError(f"保存过快，请至少间隔 {self.min_interval_ms} 毫秒后再试")

        raw = _decode_jpeg(payload.get("raw_image", ""))
        raw_sha = hashlib.sha256(raw).hexdigest()
        existing = next(
            (
                row for row in self._rows()
                if row.get("sha256") == raw_sha and row.get("review_state") != "deleted"
            ),
            None,
        )
        if existing:
            return {
                "ok": True,
                "duplicate": True,
                "message": "这张原始图片已经保存过，本次没有重复写入",
                "sample": existing,
                "status": self.status(),
            }

        with Image.open(io.BytesIO(raw)) as source:
            image = ImageOps.exif_transpose(source).convert("RGB")
        width, height = image.size
        if width < 320 or height < 240:
            raise ValueError(f"图片分辨率过低：{width}×{height}")

        status, kind, bbox, point, visibility = self._validate_label(payload, width, height)
        prediction_age = float(payload.get("prediction_age_ms", 0) or 0)
        if review_state == "pending_review" and status == "device" and prediction_age > 250:
            raise ValueError(f"预测结果已经过期（{prediction_age:.0f}ms），请等待最新设备框后再保存")

        phash = _phash(image)
        nearest, distance = self._nearest(phash, session.session_id)
        if nearest is not None and distance <= self.phash_distance:
            raise ValueError(
                f"画面与已保存样本过于相似（感知哈希距离 {distance}），"
                "请改变设备位置、角度或等待画面变化后再保存"
            )

        sharpness = _sharpness(image)
        warnings: list[str] = []
        if sharpness < 80:
            warnings.append("image_blurry")
        if point is None and status == "device":
            warnings.append("missing_contact")
        sample_id = f"sample_{timestamp}_{uuid4().hex[:8]}"
        session_root = self.data_root / session.split / session.session_id
        paths = {
            "raw": session_root / "images" / f"{sample_id}.jpg",
            "annotation": session_root / "annotations" / f"{sample_id}.json",
            "label": session_root / "labels" / f"{sample_id}.txt",
            "prediction": session_root / "predictions" / f"{sample_id}.json",
            "preview": session_root / "preview" / f"{sample_id}.jpg",
        }
        settings = payload.get("inference_settings") or {}
        now = _now()
        annotation = {
            "sample_id": sample_id,
            "session": asdict(session),
            "status": status,
            "bbox": bbox,
            "contact_point": point,
            "contact_visibility": visibility,
            "sample_kind": kind,
            "review_state": review_state,
            "annotation_state": review_state,
            "capture_timestamp_ms": timestamp,
            "frame_id": payload.get("frame_id"),
            "image_width": width,
            "image_height": height,
            "raw_sha256": raw_sha,
            "perceptual_hash": phash,
            "sharpness_score": sharpness,
            "quality_warnings": warnings,
            "prediction_age_ms": prediction_age,
            "inference_settings": settings,
            "inference_configuration_hash": settings.get("configuration_hash", ""),
            "captured_at": now,
            "updated_at": now,
        }
        _atomic(paths["raw"], raw)
        try:
            _atomic(
                paths["annotation"],
                json.dumps(annotation, ensure_ascii=False, indent=2).encode("utf-8"),
            )
            _atomic(
                paths["prediction"],
                json.dumps(
                    payload.get("prediction_snapshot") or {},
                    ensure_ascii=False,
                    indent=2,
