            "sample_id": sample_id,
            "session_id": session.session_id,
            "anonymous_subject_id": session.anonymous_subject_id,
            "split": session.split,
            "captured_at": now,
            "capture_timestamp_ms": timestamp,
            "frame_id": payload.get("frame_id", ""),
            "status": status,
            "sample_kind": kind,
            "contact_visibility": visibility,
            "raw_image_path": str(paths["raw"].relative_to(self.root)),
            "annotation_path": str(paths["annotation"].relative_to(self.root)),
            "yolo_label_path": str(paths["label"].relative_to(self.root)),
            "prediction_snapshot_path": str(paths["prediction"].relative_to(self.root)),
            "preview_path": str(paths["preview"].relative_to(self.root)),
            "width": width,
            "height": height,
            "sha256": raw_sha,
            "perceptual_hash": phash,
            "sharpness_score": f"{sharpness:.4f}",
            "inference_configuration_hash": settings.get("configuration_hash", ""),
            "prediction_age_ms": f"{prediction_age:.2f}",
            "review_state": review_state,
            "annotation_state": review_state,
            "quality_warnings": json.dumps(warnings, ensure_ascii=False),
            "nearest_sample_id": nearest.get("sample_id", "") if nearest else "",
            "nearest_phash_distance": distance if nearest else "",
            "duplicate_group": "",
