    @staticmethod
    def _yolo(
        bbox: list[float] | None,
        width: int,
        height: int,
        review_state: str,
    ) -> str:
        if bbox is None or review_state != "confirmed":
            return ""
        x1, y1, x2, y2 = bbox
        return (
            f"0 {((x1 + x2) / 2) / width:.8f} {((y1 + y2) / 2) / height:.8f} "
            f"{(x2 - x1) / width:.8f} {(y2 - y1) / height:.8f}\\n"
        )

    def quick_save(self, payload: dict[str, Any], status: str) -> dict[str, Any]:
        with self._lock:
            payload = dict(payload)
            payload["status"] = status
            payload["sample_kind"] = (
                "false_positive_no_device" if status == "no_device" else "correct_as_is"
            )
            if status == "no_device":
                payload.update({
                    "bbox": None,
                    "contact_point": None,
                    "contact_visibility": "not_annotatable",
                })
            return self._save(payload, "pending_review")

    def save_confirmed(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self._lock:
            if payload.get("annotation_state") != "confirmed":
                raise ValueError("模型预测草稿必须经过人工确认后才能进入训练集")
            return self._save(payload, "confirmed")

    def list_samples(
        self,
        *,
        review_state: str | None = None,
        split: str | None = None,
        quality: str | None = None,
        status: str | None = None,
        limit: int = 100,
        offset: int = 0,
    ) -> dict[str, Any]:
        with self._lock:
            rows = self._rows()
            if review_state and review_state != "all":
                rows = [row for row in rows if row.get("review_state") == review_state]
            if split and split != "all":
                rows = [row for row in rows if row.get("split") == split]
            if status and status != "all":
                rows = [row for row in rows if row.get("status") == status]
            if quality and quality != "all":
                def matches(row: dict[str, str]) -> bool:
                    warnings = json.loads(row.get("quality_warnings") or "[]")
                    if quality == "near_duplicate":
                        return bool(row.get("nearest_sample_id")) and str(row.get("nearest_phash_distance", "")).isdigit() and int(row["nearest_phash_distance"]) <= self.phash_distance
                    if quality == "blurry":
                        return "image_blurry" in warnings
                    if quality == "missing_contact":
                        return "missing_contact" in warnings
                    return True
                rows = [row for row in rows if matches(row)]
            rows.sort(key=lambda row: row.get("captured_at", ""), reverse=True)
            total = len(rows)
            limit = max(1, min(int(limit), 200))
            offset = max(0, int(offset))
            return {
                "items": rows[offset:offset + limit],
                "total": total,
                "limit": limit,
                "offset": offset,
            }

    def sample_detail(self, sample_id: str) -> dict[str, Any]:
        with self._lock:
            _, row, _ = self._row(sample_id)
            annotation = _json_load(self._path(row["annotation_path"]))
            prediction = _json_load(self._path(row["prediction_snapshot_path"]))
            annotation.setdefault("review_state", row.get("review_state", "confirmed"))
            annotation.setdefault("status", row.get("status", "device"))
            return {"sample": row, "annotation": annotation, "prediction": prediction}

    def image_path(self, sample_id: str) -> Path:
        with self._lock:
            _, row, _ = self._row(sample_id)
            return self._path(row["raw_image_path"])

    def review(self, sample_id: str, payload: dict[str, Any]) -> dict[str, Any]:
        with self._lock:
            index, row, rows = self._row(sample_id)
            image_path = self._path(row["raw_image_path"])
            with Image.open(image_path) as source:
                image = ImageOps.exif_transpose(source).convert("RGB")
            width, height = image.size
            status, kind, bbox, point, visibility = self._validate_label(payload, width, height)
            annotation_path = self._path(row["annotation_path"])
            annotation = _json_load(annotation_path)
            now = _now()
            annotation.update({
                "status": status,
                "sample_kind": kind,
                "bbox": bbox,
                "contact_point": point,
                "contact_visibility": visibility,
                "review_state": "confirmed",
                "annotation_state": "confirmed",
                "reviewed_at": now,
                "updated_at": now,
            })
            warnings = [
                warning for warning in annotation.get("quality_warnings", [])
                if warning != "missing_contact"
            ]
            if status == "device" and point is None:
                warnings.append("missing_contact")
            annotation["quality_warnings"] = warnings
            _atomic(
                annotation_path,
                json.dumps(annotation, ensure_ascii=False, indent=2).encode("utf-8"),
            )
            _atomic(
                self._path(row["yolo_label_path"]),
                self._yolo(bbox, width, height, "confirmed").encode("ascii"),
            )
            self._write_preview(image, bbox, point, self._path(row["preview_path"]))
            row.update({
                "status": status,
                "sample_kind": kind,
                "contact_visibility": visibility,
                "review_state": "confirmed",
                "annotation_state": "confirmed",
                "quality_warnings": json.dumps(warnings, ensure_ascii=False),
                "updated_at": now,
                "deleted_at": "",
            })
            rows[index] = row
            self._rewrite(rows)
            return {"ok": True, "message": "人工审查结果已保存", "sample": row, "status": self.status()}

    @staticmethod
    def _write_preview(
        image: Image.Image,
        bbox: list[float] | None,
        point: list[float] | None,
        path: Path,
    ) -> None:
        preview = image.copy()
        draw = ImageDraw.Draw(preview)
        if bbox:
            draw.rectangle(tuple(bbox), outline=(32, 210, 112), width=6)
        if point:
            x, y = point
            radius = max(8, min(image.size) // 70)
            draw.ellipse((x - radius, y - radius, x + radius, y + radius), outline=(0, 220, 255), width=5)
            draw.line((x - radius * 2, y, x + radius * 2, y), fill=(0, 220, 255), width=4)
            draw.line((x, y - radius * 2, x, y + radius * 2), fill=(0, 220, 255), width=4)
        stream = io.BytesIO()
        preview.save(stream, format="JPEG", quality=92)
        _atomic(path, stream.getvalue())

    def delete(self, sample_id: str) -> dict[str, Any]:
        with self._lock:
            index, row, rows = self._row(sample_id)
            if row.get("review_state") == "deleted":
                return {"ok": True, "message": "样本已经处于删除状态", "sample": row}
            now = _now()
            row.update({
                "review_state": "deleted",
                "annotation_state": "deleted",
                "updated_at": now,
                "deleted_at": now,
            })
            annotation = _json_load(self._path(row["annotation_path"]))
            annotation.update({"review_state": "deleted", "annotation_state": "deleted", "deleted_at": now, "updated_at": now})
            _atomic(self._path(row["annotation_path"]), json.dumps(annotation, ensure_ascii=False, indent=2).encode("utf-8"))
            _atomic(self._path(row["yolo_label_path"]), b"")
            rows[index] = row
            self._rewrite(rows)
            return {"ok": True, "message": "样本已软删除，可在已删除筛选中恢复", "sample": row, "status": self.status()}

    def restore(self, sample_id: str) -> dict[str, Any]:
        with self._lock:
            index, row, rows = self._row(sample_id)
            if row.get("review_state") != "deleted":
                raise ValueError("只有已删除样本可以恢复")
            now = _now()
            row.update({
                "review_state": "pending_review",
                "annotation_state": "pending_review",
                "updated_at": now,
                "deleted_at": "",
            })
            annotation = _json_load(self._path(row["annotation_path"]))
            annotation.update({"review_state": "pending_review", "annotation_state": "pending_review", "deleted_at": "", "updated_at": now})
            _atomic(self._path(row["annotation_path"]), json.dumps(annotation, ensure_ascii=False, indent=2).encode("utf-8"))
            rows[index] = row
            self._rewrite(rows)
            return {"ok": True, "message": "样本已恢复到待审查队列", "sample": row, "status": self.status()}

    def status(self) -> dict[str, Any]:
        rows = self._rows()
        counts = {
            split: {
                "device": 0,
                "no_device": 0,
                "total": 0,
                "pending_review": 0,
                "confirmed": 0,
                "deleted": 0,
            }
            for split in SPLITS
        }
        for row in rows:
            split = row.get("split", "")
            if split not in counts:
                continue
            state = row.get("review_state") or row.get("annotation_state") or "confirmed"
            if state in REVIEW_STATES:
                counts[split][state] += 1
            if state == "confirmed" and row.get("status") in {"device", "no_device"}:
                counts[split][row["status"]] += 1
                counts[split]["total"] += 1
        targets = {
            "train": {"device": 60, "no_device": 60},
            "val": {"device": 20, "no_device": 20},
            "test": {"device": 20, "no_device": 20},
        }
        remaining = {
            split: {
                label: max(0, target - counts[split][label])
                for label, target in values.items()
            }
            for split, values in targets.items()
        }
        return {
            "active_session": asdict(self._active) if self._active else None,
            "counts": counts,
            "targets": targets,
            "remaining": remaining,
            "training_ready": all(
                value == 0 for values in remaining.values() for value in values.values()
            ),
            "root": str(self.root),
        }
