const js=`"use strict";

(() => {
  const PROFILE_KEY = "medvision-active-learning-profile-v2";
  const style = document.createElement("style");
  style.textContent = \`
    .quick-capture{margin:18px 0;padding:18px;background:#fffdf7;border:2px solid #d2a938;border-radius:14px}
    .quick-capture h2{margin:0 0 6px}.quick-note{color:#4b5b52;line-height:1.65}
    .quick-actions{display:flex;gap:9px;flex-wrap:wrap;margin:12px 0}
    .quick-actions button,.quick-actions a{padding:10px 15px;border:0;border-radius:9px;color:#fff;font-weight:800;text-decoration:none;cursor:pointer}
    .quick-device{background:#1769e0}.quick-negative{background:#9b542e}.quick-review{background:#17775a}.quick-session{background:#6f735f}
    .quick-actions button:disabled{opacity:.48;cursor:not-allowed}
    .quick-settings{margin:10px 0;padding:10px;background:#f5f0df;border-radius:10px}
    .quick-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:8px;margin-top:9px}
    .quick-fields label{display:flex;flex-direction:column;gap:5px;font-weight:700}
    .quick-fields input,.quick-fields select{padding:8px;border:1px solid #bdb49f;border-radius:7px;background:#fff}
    .quick-status{padding:11px;border-left:4px solid #17775a;background:#edf7f1;line-height:1.55;font-weight:700}
    .quick-status.error{border-color:#b34b2d;background:#fff0e9;color:#8b2f18}
    .quick-counts{margin-top:8px;color:#415047;font:700 13px ui-monospace,monospace;white-space:pre-wrap}
    .quick-last{display:flex;gap:10px;align-items:center;margin-top:10px}.quick-last img{width:110px;height:72px;object-fit:cover;border-radius:8px;border:1px solid #c9bea5}
  \`;
  document.head.appendChild(style);

  const panel = document.createElement("section");
  panel.className = "quick-capture";
  panel.innerHTML = \`
    <h2>摄像头一键采集</h2>
    <p class="quick-note">视频与推理不会暂停。设备样本保存“最近一次完整推理对应的原始帧”；无设备样本保存点击按钮时的原始画面。新样本先进入待审查，不会直接用于训练。</p>
    <div class="quick-actions">
      <button id="quick-device" class="quick-device" disabled>一键保存设备样本</button>
      <button id="quick-no-device" class="quick-negative" disabled>一键保存无设备帧</button>
      <a class="quick-review" href="/active-learning/review" target="_blank">打开样本审查页</a>
      <button id="quick-new-session" class="quick-session">新建独立 Session</button>
    </div>
    <details id="quick-settings">
      <summary><strong>采集设置</strong>（首次设置后自动记住）</summary>
      <div class="quick-fields">
        <label>匿名人物 ID<input id="quick-subject" value="subject_A"></label>
        <label>数据划分<select id="quick-split"><option value="train">train</option><option value="val">val</option><option value="test">test</option><option value="cross_subject_test">cross_subject_test</option></select></label>
        <label>背景 ID<input id="quick-background" value="office_01"></label>
        <label>眼镜状态<select id="quick-glasses"><option value="glasses">戴眼镜</option><option value="no_glasses">不戴眼镜</option><option value="unknown">未知</option></select></label>
        <label>光照<select id="quick-lighting"><option value="normal">正常</option><option value="bright">偏亮</option><option value="dark">偏暗</option><option value="mixed">混合</option></select></label>
      </div>
    </details>
    <div id="quick-status" class="quick-status">正在读取采集状态...</div>
    <div id="quick-counts" class="quick-counts"></div>
    <div id="quick-last" class="quick-last" hidden><img alt="最近保存样本"><span></span></div>
  \`;
  (document.querySelector(".steps") || document.querySelector("main").lastElementChild).before(panel);

  const q = id => panel.querySelector(id);
  const deviceButton = q("#quick-device");
  const negativeButton = q("#quick-no-device");
  const statusBox = q("#quick-status");
  let activeSession = null;
  let saving = false;

  function profile() {
    return {
      anonymous_subject_id: q("#quick-subject").value.trim(),
      split: q("#quick-split").value,
      background_id: q("#quick-background").value.trim() || "unknown",
      glasses: q("#quick-glasses").value,
      lighting: q("#quick-lighting").value,
    };
  }

  function restoreProfile() {
    try {
      const data = JSON.parse(localStorage.getItem(PROFILE_KEY) || "{}");
      const map = {anonymous_subject_id:"#quick-subject",split:"#quick-split",background_id:"#quick-background",glasses:"#quick-glasses",lighting:"#quick-lighting"};
      for (const [key, selector] of Object.entries(map)) if (data[key]) q(selector).value = data[key];
    } catch (_) {}
  }

  function saveProfile() {
    localStorage.setItem(PROFILE_KEY, JSON.stringify(profile()));
  }

  function show(message, error=false) {
    statusBox.textContent = message;
    statusBox.className = "quick-status" + (error ? " error" : "");
  }

  function validBox(box) {
    return Array.isArray(box) && box.length === 4 && box.every(Number.isFinite) &&
      box[2] - box[0] >= 4 && box[3] - box[1] >= 4;
  }

  function validPoint(point) {
    return Array.isArray(point) && point.length === 2 && point.every(Number.isFinite);
  }

  function state() {
    return window.medvisionStreamState || null;
  }

  async function blobDataUrl(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(new Error("读取摄像头帧失败"));
      reader.readAsDataURL(blob);
    });
  }

  async function ensureSession(forceNew=false) {
    if (activeSession && !forceNew) return activeSession;
    if (forceNew && activeSession) {
      const stopped = await fetch("/v1/active-learning/session/stop", {method:"POST"}).then(r => r.json());
      if (!stopped.ok) throw new Error(stopped.error || "结束旧 Session 失败");
      activeSession = null;
    }
    saveProfile();
    const response = await fetch("/v1/active-learning/session/start", {
      method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(profile()),
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error || "创建采集 Session 失败");
    renderStatus(data);
    return activeSession;
  }

  function renderStatus(data) {
    activeSession = data.active_session || null;
    const c = data.counts || {};
    const pending = Object.values(c).reduce((n, row) => n + Number(row.pending_review || 0), 0);
    const confirmed = Object.values(c).reduce((n, row) => n + Number(row.confirmed || 0), 0);
    q("#quick-counts").textContent =
      \`当前 Session：\${activeSession ? activeSession.session_id + " / " + activeSession.split : "未创建，将在首次保存时自动创建"}\\n\` +
      \`待审查：\${pending}，已确认可训练：\${confirmed}，训练门禁：\${data.training_ready ? "已达到" : "未达到"}\`;
  }

  function showSaved(data) {
    const sample = data.sample || {};
    const last = q("#quick-last");
    last.hidden = false;
    last.querySelector("img").src = \`/v1/active-learning/samples/\${sample.sample_id}/image?t=\${Date.now()}\`;
    last.querySelector("span").textContent = data.duplicate
      ? "这张原图已经保存过，没有重复写入。"
      : \`已保存到待审查队列：\${sample.sample_id}\`;
    show(data.message || "保存成功，样本已进入待审查队列。");
    if (data.status) renderStatus(data.status);
  }

  async function quickDevice() {
    if (saving) return;
    const stream = state();
    const pair = stream?.latestPair?.();
    if (!pair) return show("还没有可保存的完整推理帧，请先启动摄像头并等待设备框。", true);
    const age = Date.now() - pair.receivedAt;
    const box = pair.result?.device_bbox;
    if (age > 250) return show(\`最新设备框已经过期（\${age}ms），请等待下一次稳定结果后再保存。\`, true);
    if (!validBox(box)) return show("当前帧没有合法设备框，不能保存设备样本。", true);
    saving = true; deviceButton.disabled = true;
    try {
      await ensureSession();
      const point = validPoint(pair.result.contact_point) ? pair.result.contact_point : null;
      const payload = {
        raw_image: await blobDataUrl(pair.blob),
        capture_timestamp_ms: pair.captureTimestampMs,
        prediction_age_ms: age,
        bbox: box,
        contact_point: point,
        contact_visibility: point ? (pair.result.contact_visibility || "visible") : "not_annotatable",
        prediction_snapshot: pair.result,
        inference_settings: pair.settings || {},
        source_frame_id: pair.frameId,
      };
      const response = await fetch("/v1/active-learning/quick/device", {
        method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload),
      });
      const data = await response.json();
      if (!data.ok) throw new Error(data.error || "保存设备样本失败");
      showSaved(data);
    } catch (error) {
      show("保存失败：" + error.message, true);
    } finally {
      saving = false;
    }
  }

  async function quickNoDevice() {
    if (saving) return;
    const video = state()?.video?.();
    if (!video || !video.videoWidth) return show("请先启动摄像头，再保存无设备画面。", true);
    saving = true; negativeButton.disabled = true;
    try {
      await ensureSession();
      const canvas = document.createElement("canvas");
      canvas.width = video.videoWidth; canvas.height = video.videoHeight;
      canvas.getContext("2d").drawImage(video,0,0,canvas.width,canvas.height);
      const payload = {
        raw_image: canvas.toDataURL("image/jpeg",0.88),
        capture_timestamp_ms: Date.now(),
        prediction_age_ms: 0,
        prediction_snapshot: state()?.latest?.() || {},
        inference_settings: state()?.settings?.() || {},
      };
      const response = await fetch("/v1/active-learning/quick/no-device", {
        method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload),
      });
      const data = await response.json();
      if (!data.ok) throw new Error(data.error || "保存无设备样本失败");
