  const stage=document.querySelector('#stage'),startBtn=document.querySelector('#start'),freezeBtn=document.querySelector('#freeze'),confirmBtn=document.querySelector('#confirm'),cancelBtn=document.querySelector('#cancel'),resetBtn=document.querySelector('#reset'),stopBtn=document.querySelector('#stop'),statusEl=document.querySelector('#status'),backgroundBtn=document.querySelector('#background-toggle'),manualModeBtn=document.querySelector('#manual-mode'),markerModeBtn=document.querySelector('#marker-mode');
  let media=null,timer=null,raf=null,inFlight=false,frameId=0,latest=null,responses=0,fpsStart=performance.now(),frozen=false,dragStart=null,draftBox=null,manualEnabled=false,markerEnabled=false,whitenBackground=true;
