  function setBadge(id,label,enabled){const el=document.querySelector(id);el.textContent=`${label}：${enabled?'开启':'关闭'}`;el.className='badge '+(enabled?'on':'off')}
  function applyModes(modes){manualEnabled=Boolean(modes.enable_manual_bbox_assist);markerEnabled=Boolean(modes.enable_marker_assist);setBadge('#manual-mode','手动画框',manualEnabled);setBadge('#marker-mode','AprilTag',markerEnabled);document.querySelectorAll('.manual-control').forEach(element=>element.classList.toggle('hidden',!manualEnabled));freezeBtn.disabled=!media||!manualEnabled;if(!manualEnabled&&frozen)cancelSelection()}
  async function updateModes(nextManual,nextMarker){manualModeBtn.disabled=true;markerModeBtn.disabled=true;try{const response=await fetch('/v1/assist/modes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enable_manual_bbox_assist:nextManual,enable_marker_assist:nextMarker})});const data=await response.json();if(!data.ok)throw new Error(data.error);applyModes(data.assist_modes);status(`辅助模式已更新：手动画框${manualEnabled?'开启':'关闭'}，AprilTag${markerEnabled?'开启':'关闭'}。`)}catch(error){status('辅助模式更新失败：'+error.message,true)}finally{manualModeBtn.disabled=false;markerModeBtn.disabled=false}}
  function fit(){if(!video.videoWidth)return;for(const target of [canvas,capture,seed]){target.width=video.videoWidth;target.height=video.videoHeight}}
  function drawBox(box,color,label,width=6,dashed=false){if(!box)return;const[x1,y1,x2,y2]=box;ctx.save();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dashed?[14,8]:[]);ctx.strokeRect(x1,y1,x2-x1,y2-y1);ctx.setLineDash([]);ctx.fillStyle=color;ctx.font='bold 20px sans-serif';ctx.fillText(label,x1+6,Math.max(24,y1+24));ctx.restore()}
  function drawPoint(point){if(!point)return;const[x,y]=point,r=Math.max(12,Math.min(canvas.width,canvas.height)*.017);ctx.save();ctx.strokeStyle='#f34ca8';ctx.lineWidth=6;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(x-r-7,y);ctx.lineTo(x+r+7,y);ctx.moveTo(x,y-r-7);ctx.lineTo(x,y+r+7);ctx.stroke();ctx.restore()}
  function drawMarkers(markers){for(const marker of markers||[]){const points=marker.corners||[];if(points.length!==4)continue;ctx.save();ctx.strokeStyle='#18a56f';ctx.fillStyle='#18a56f';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<4;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.stroke();ctx.font='bold 22px sans-serif';ctx.fillText(`Tag ${marker.marker_id}`,points[0][0]+5,Math.max(24,points[0][1]-8));ctx.restore()}}
  function drawLiveFrame(){const polygon=latest&&Array.isArray(latest.foreground_polygon)?latest.foreground_polygon:[];if(!whitenBackground||polygon.length<3){ctx.drawImage(video,0,0,canvas.width,canvas.height);return}ctx.save();ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.beginPath();ctx.moveTo(polygon[0][0],polygon[0][1]);for(let i=1;i<polygon.length;i++)ctx.lineTo(polygon[i][0],polygon[i][1]);ctx.closePath();ctx.clip();ctx.drawImage(video,0,0,canvas.width,canvas.height);ctx.restore()}
  function paint(){if(canvas.width){if(frozen)ctx.drawImage(seed,0,0);else if(video.videoWidth)drawLiveFrame();if(!frozen&&latest){drawMarkers(latest.marker_corners);drawBox(latest.diagnostic_bbox,'#f58b23','自动候选',4);drawBox(latest.device_bbox,latest.state==='CANDIDATE'?'#f58b23':'#ed3343',latest.state||'TRACKING');drawPoint(latest.contact_point);if(latest.needs_review&&latest.state!=='SEARCHING'){ctx.fillStyle='#ffd64a';ctx.font='bold 22px sans-serif';ctx.fillText('需复查：'+(latest.review_reasons||[]).join(', '),14,32)}}if(draftBox)drawBox(draftBox,'#ffd64a','当前手动画框',5,true)}raf=requestAnimationFrame(paint)}
