  function updateMetrics(sent){document.querySelector('#state').textContent=latest.state||latest.track_state;document.querySelector('#source').textContent=latest.assist_source||'-';document.querySelector('#marker-ids').textContent=(latest.visible_marker_ids||[]).join(', ')||'无';document.querySelector('#marker-source').textContent=latest.marker_source||'none';document.querySelector('#marker-score').textContent=Number(latest.marker_confidence||0).toFixed(3);document.querySelector('#device-score').textContent=Number(latest.device_score||latest.detector_score||0).toFixed(3);document.querySelector('#contact-state').textContent=latest.contact_visibility||'not_annotatable';document.querySelector('#latency').textContent=`${Number(latest.timings_ms?.total||0).toFixed(1)} / ${(performance.now()-sent).toFixed(1)} ms`;const now=performance.now();if(now-fpsStart>=1000){document.querySelector('#fps').textContent=`${responses} FPS`;responses=0;fpsStart=now}}
