class ActiveLearningCaptureStore:
    """Capture pending samples and expose an auditable review workflow."""

    def __init__(self, root: Path, min_interval_ms: int = 400, phash_distance: int = 4):
        self.root = root
        self.data_root = root / "sessions"
        self.manifest_root = root / "manifests"
        self.min_interval_ms = min_interval_ms
        self.phash_distance = phash_distance
        self._lock = threading.RLock()
        self._active: ActiveSession | None = None
        self._last_timestamp_ms: int | None = None
        root.mkdir(parents=True, exist_ok=True)
        self._migrate_manifest()

    @property
    def manifest_path(self) -> Path:
        return self.manifest_root / "samples.csv"

    @property
    def dataset_split_path(self) -> Path:
        return self.manifest_root / "dataset_split_v1.csv"

    def _dataset_split_rows(self) -> list[dict[str, str]]:
        return _read_csv(self.dataset_split_path)

    def _dataset_split_map(self) -> dict[str, str]:
        return {
            row["sample_id"]: row["dataset_split"]
            for row in self._dataset_split_rows()
            if row.get("sample_id") and row.get("dataset_split") in {"train", "val", "test"}
        }

    def _public_row(
        self, row: dict[str, str], split_map: dict[str, str] | None = None
    ) -> dict[str, str]:
        result = dict(row)
        result["capture_split"] = row.get("split", "")
        result["dataset_split"] = (split_map or self._dataset_split_map()).get(
            row.get("sample_id", ""), row.get("split", "")
        )
        result["split"] = result["dataset_split"]
        return result

    def _assign_dataset_split(self, row: dict[str, Any]) -> str:
        split_rows = self._dataset_split_rows()
        for existing in split_rows:
            if existing.get("sample_id") == row.get("sample_id"):
                return existing.get("dataset_split", row.get("split", "train"))
        capture_split = str(row.get("split", "train"))
        if capture_split != "train":
            assigned = capture_split
        else:
            source_video_id = str(row.get("source_video_id", ""))
            session_id = str(row.get("session_id", ""))
            sequence_count = sum(
                1 for item in split_rows
                if (
                    source_video_id
                    and item.get("source_video_id") == source_video_id
                ) or (
                    not source_video_id
                    and not item.get("source_video_id")
                    and item.get("session_id") == session_id
                )
            )
            assigned = AUTO_SPLIT_PATTERN[sequence_count % len(AUTO_SPLIT_PATTERN)]
        split_rows.append({
            "sample_id": row.get("sample_id", ""),
            "dataset_split": assigned,
            "status": row.get("status", ""),
            "session_id": row.get("session_id", ""),
            "source_video_id": row.get("source_video_id", ""),
            "raw_image_path": row.get("raw_image_path", ""),
            "sha256": row.get("sha256", ""),
            "review_state": row.get("review_state", ""),
            "seed": 42,
        })
        _write_dataset_split_csv(self.dataset_split_path, split_rows)
        return assigned

    def _migrate_manifest(self) -> None:
        rows = _read_csv(self.manifest_path)
        if not rows:
            return
        existing_fields = set(rows[0])
        if set(SAMPLE_FIELDS).issubset(existing_fields):
            return
        backup = self.manifest_root / "samples.pre_review_revision_v3.csv"
        if not backup.exists():
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(self.manifest_path, backup)
        migrated = []
        for row in rows:
            state = row.get("review_state") or row.get("annotation_state") or "confirmed"
            if state not in REVIEW_STATES:
                state = "confirmed"
            row.update({
                "frame_id": row.get("frame_id", ""),
                "preview_path": row.get("preview_path", ""),
                "prediction_age_ms": row.get("prediction_age_ms", ""),
                "review_state": state,
                "annotation_state": state,
                "quality_warnings": row.get("quality_warnings", "[]") or "[]",
                "nearest_sample_id": row.get("nearest_sample_id", ""),
                "nearest_phash_distance": row.get("nearest_phash_distance", ""),
                "duplicate_group": row.get("duplicate_group", ""),
                "review_revision": row.get("review_revision") or (
                    "1" if state == "confirmed" else "0"
                ),
                "updated_at": row.get("updated_at") or row.get("captured_at") or _now(),
                "deleted_at": row.get("deleted_at", ""),
            })
            migrated.append(row)
        self._rewrite(migrated)

    def _rewrite(self, rows: list[dict[str, Any]]) -> None:
        _write_csv(self.manifest_path, rows)
        grouped: dict[tuple[str, str], list[dict[str, Any]]] = {}
        for row in rows:
            grouped.setdefault((row["split"], row["session_id"]), []).append(row)
        for (split, session_id), session_rows in grouped.items():
            _write_csv(self.data_root / split / session_id / "samples.csv", session_rows)

    def _rows(self) -> list[dict[str, str]]:
        return _read_csv(self.manifest_path)

    def _row(self, sample_id: str) -> tuple[int, dict[str, str], list[dict[str, str]]]:
        rows = self._rows()
        for index, row in enumerate(rows):
            if row.get("sample_id") == sample_id:
